// Retrieve the session stored when Python last sent a packet.
// Drop DCN packets until the TCP session is established.
var session = flow.get('tcp_session');
if (!session) {
    return null;
}

var raw;
if (Buffer.isBuffer(msg.payload)) {
    raw = msg.payload.toString('ascii').trim();
} else {
    raw = String(msg.payload).trim();
}
if (!raw.startsWith('/')) return null;
if (!raw.endsWith('\r')) raw = raw + '\r';
msg.payload = Buffer.from(raw, 'ascii');
msg._session = session;
return msg;

// Always capture the session first — even for the initial CR ping.
// This makes the serial→Python path ready before Python sends any real command.
if (msg._session) {
    flow.set('tcp_session', msg._session);
}

// Only forward valid DCN packets to serial.
var raw;
if (Buffer.isBuffer(msg.payload)) {
    raw = msg.payload.toString('ascii').trim();
} else {
    raw = String(msg.payload).trim();
}
if (!raw.startsWith('/')) return null;
if (!raw.endsWith('\r')) raw = raw + '\r';
msg.payload = Buffer.from(raw, 'ascii');
return msg;
